
<template>
  <div class="safe-center-account">
    <title-line :title="title" />
    <div class="content">
      <div class="box">
        <van-form @submit="onSubmit">
          <div class="title">{{ $t('aqzx.aqzx58') }}</div>
          <van-field
            v-model="loginname"
            name="账号"
            label=""
            :placeholder="$t('aqzx.aqzx59')"
            autocomplete="off"
            :rules="[{ required: true, message: $t('aqzx.aqzx59') }]"
          />
          <div class="title">{{ $t('aqzx.aqzx52') }}</div>
          <van-field
            v-model="loginpwd"
            style="margin-top:10px"
            :type="passwordType"
            name="登录密码"
            label=""
            :placeholder="$t('aqzx.aqzx16')"
            :rules="[{ required: true, message: $t('aqzx.aqzx16') },
                     {pattern:/^(?=.*[A-Z])(?=.*[a-z])(?=.*[0-9])[a-zA-Z0-9]{6,20}$/,message:'请输入6至20位小写字母, 大写字母和数字的组合',trigger:'onBlur'}
            ]"
          >
            <template slot="right-icon">
              <span class="soltseye" @click="switchPasswordType">
                <van-icon v-if="passwordType==='password'" name="eye" />
                <van-icon v-else name="closed-eye" />
              </span>
            </template>
          </van-field>
          <div class="title">{{ $t('aqzx.aqzx52') }}</div>
          <van-field
            v-model="confirmpwd"
            style="margin-top:10px"
            :type="passwordType1"
            name="确认登录密码"
            label=""
            autocomplete="off"
            :placeholder="$t('aqzx.aqzx16')"
            :rules="[{ required: true, message: $t('aqzx.aqzx16') }]"
          >
            <template slot="right-icon">
              <span class="soltseye" @click="switchPasswordType1">
                <van-icon v-if="passwordType1==='password'" name="eye" />
                <van-icon v-else name="closed-eye" />
              </span>
            </template>
          </van-field>
          <div style="margin: 40px auto 10px;">
            <van-button
              class="btn-bg"
              block
              type="info"
              native-type="submit"
            >提交</van-button>
          </div>
        </van-form>
      </div>
    </div>

  </div>
</template>
<script>
import TitleLine from './modules/TitleLine'
import { setloginname } from '@/api/safe'
export default {
  components: {
    TitleLine
  },
  props: {
  },
  data() {
    return {
      title: '设置账号',
      loginname: '',
      loginpwd: '',
      confirmpwd: '',
      passwordType: 'password',
      passwordType1: 'password',
      pattern: '^(?=.*[A-Z])(?=.*[a-z])(?=.*[0-9])[a-zA-Z0-9]{6,20}$'
    }
  },
  methods: {
    switchPasswordType() {
      this.passwordType = this.passwordType === 'password' ? 'text' : 'password'
    },
    switchPasswordType1() {
      this.passwordType1 = this.passwordType1 === 'password' ? 'text' : 'password'
    },
    // goMore() {
    //   this.$router.push({ path: '/rechargeRecord' })
    // }
    // getEcode(email) {
    //   sendmail({ email: email }).then(res => {
    //     if (res.status === '1') {
    //       this.$toast('发送成功')
    //     }
    //   })
    // },
    onSubmit() {
      if (this.loginpwd !== this.confirmpwd) {
        this.$toast(this.$t('aqzx.aqzx56'))
        return false
      }
      setloginname({ loginname: this.loginname, loginpwd: this.loginpwd }).then(res => {
        if (res.status === '1') {
          this.$toast(this.$t('aqzx.aqzx49'))
          setTimeout(() => {
            this.$router.push({ path: '/safeCenter' })
          }, 2000)
        }
      })
    }
  }

}
</script>
<style lang="scss" scoped>
.safe-center-account {
    min-height: 100vh;
    width: 100%;
    background: var(--inner-bg-color);
    background-position: 0% 0%;
    background-size: 100% 100%;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
    .containers{
    position: relative;
    // padding: 0px 30px 0px;
    }
    .content{
        margin: auto 28px;
        .box {
          margin-top: 36px;
          padding: 40px;
          border-radius: 28px;
          background: rgba(241, 229, 255,0.12);
          border-radius: 8px;
        .title {
            margin-bottom: 16px;
            font-family: PingFangSC-Regular;
            font-size: 28px;
            color: rgba(255, 255, 255,0.75);
            letter-spacing: 0;
            line-height: 40px;
            font-weight: 400;
        }
        .title:not(:first-child){
          margin-top: 40px;
        }
        .tips {
            color: #fff;
            position: relative;
            .warning_icon {
                position: absolute;
                top: 6px;
                width: 20px;
                height: 20px;
                background-image: url(~@/assets/portal/warning_icon.png);
                background-position: 0% 0%;
                background-size: 100% 100%;
                background-repeat: no-repeat;
            }
            span {
                margin-left: 28px;
            }
        }
        .forgetPsd{
            text-align: center;
            font-family: PingFangSC-Regular;
            font-size: 28px;
            color: #00B7FF;
            font-weight: 400;
        }
     }
    }

}
</style>
